  name: 'List to page · on the page',
  args: {
    size: 'lg',
    inset: 24
  },
  render: args => <Opener label="Open Needs attention" args={args}>
      <NeedsAttention />
    </Opener>,
  play: async ({
    canvasElement
  }) => {
    await userEvent.click(within(canvasElement).getByRole('button', {
      name: 'Open Needs attention'
    }));
    const body = within(canvasElement.ownerDocument.body);
    await userEvent.click(await body.findByRole('button', {
      name: /125 hosts/
    }));
    await expect(await body.findByRole('button', {
      name: 'Back to Needs attention'
    })).toBeInTheDocument();
  }
